// === Tab: mySketch ===
// by SamuelYAN
// more works //
// https://twitter.com/SamuelAnn0924
// https://www.instagram.com/samuel_yan_1990/

// Black Field – Astrophysical Jet
// minimal black & white universe
// galaxy disk + bipolar jet

let seed;
let mySize;
let t = 0;

function setup() {
	seed = floor(random(999999));
	randomSeed(seed);
	noiseSeed(seed);

	mySize = max(windowWidth, windowHeight);
	createCanvas(mySize, mySize, WEBGL);
	frameRate(30);
	background(0);
}

function draw() {
	// background(0);
	randomSeed(seed);

	t += 0.0001; // very slow cosmic time

	push();
	translate(0, 0, mySize * 0.5);

	// slight tilt, like astronomical observation
	rotateX(random(-PI / 2) + t * random([-1, 1]));
	rotateY(random(-PI / 2) + t * random([-1, 1]));
	rotateZ(random(-PI / 2) + t * random([-1, 1]));

	let radiusMax = mySize * 0.4;
	let layers = 100;

	// ---------- Galaxy Disk ----------
	for (let i = 0; i < layers; i++) {
		let r = map(i, 0, layers, mySize / 100, radiusMax);
		let density = exp(-r * 0.01); // exponential disk
		let count = int(20 * density);

		for (let j = 0; j < count; j++) {
			let theta =
				j * TAU / count +
				noise(r * 0.01, t) * 0.5;
			rotateX(t * random([1, 1]));
			rotateY(t * random([1, -1]));
			rotateZ(t * random([-1, 1]));

			let x = r * cos(theta);
			let y = r * sin(theta);
			let z = noise(r * 0.02, theta) * mySize * 0.01;

			let alpha = 200 + density * 120;

			stroke(255, alpha);
			strokeWeight(random(0.1, 1));
			point(x, y, z);
		}
	}

	// ---------- Astrophysical Jets ----------
	let jetLength = mySize * 0.45;
	let jetLayers = 0;

	for (let i = 0; i < jetLayers; i++) {
		let h = map(i, 0, jetLayers, -jetLength, jetLength);
		let spread = abs(h) * 0.02;
		let pulse = sin(t + h * 0.02) * 0.5 + 0.5;

		var r = spread * mySize * 0.02;
		let a = random(TAU);

		var x = r * cos(a);
		var y = r * sin(a);
		var z = h;

		stroke(255, 160 * pulse);
		strokeWeight(1);
		line(0, 0, h, x, y, h);
	}

	// ---------- Central Core ----------
	noStroke();
	fill(255, 200);
	// sphere(mySize * 0.015, 8, 8);

	pop();
}

function windowResized() {
	resizeCanvas(windowWidth, windowHeight);
	mySize = max(windowWidth, windowHeight);
}

